using System;using System.IO;using System.Threading;using System.Text;using System.Web.Script.Serialization;
public static class ModIO {
 public static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=4194304};
 public static T Read<T>(string file){using(var f=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var r=new StreamReader(f,Encoding.UTF8,true))return Json.Deserialize<T>(r.ReadToEnd());}
 public static bool Put(string path,object value,bool required=false){Directory.CreateDirectory(Path.GetDirectoryName(path));var temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllText(temp,Json.Serialize(value),new UTF8Encoding(false));try{for(int i=0;;i++){try{if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);return true;}catch(IOException){if(i>=9){if(required)throw;return false;}Thread.Sleep(Math.Min(20*(i+1),100));}catch(UnauthorizedAccessException){if(i>=9){if(required)throw;return false;}Thread.Sleep(Math.Min(20*(i+1),100));}}}finally{try{if(File.Exists(temp))File.Delete(temp);}catch{}}}
 public static void Event(string state,string kind,object details){try{var folder=Path.Combine(state,"diagnostics");Directory.CreateDirectory(folder);var file=Path.Combine(folder,"native.jsonl");if(File.Exists(file)&&new FileInfo(file).Length>1048576){if(File.Exists(file+".previous"))File.Delete(file+".previous");File.Move(file,file+".previous");}File.AppendAllText(file,Json.Serialize(new{at=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),kind=kind,details=details})+"\n",new UTF8Encoding(false));}catch{}}
}
public sealed class Identity {public int pid;public string startTicks,executable;}
public sealed class FeatureInput {public long at;public string instanceId,launcherRoot,statusFile,stateDirectory;public bool enabled;public Identity client,server;public System.Collections.Generic.Dictionary<string,object> config;public Roster roster;}
public static class Values {public static bool Flag(System.Collections.Generic.Dictionary<string,object> c,string key,bool fallback){return c!=null&&c.ContainsKey(key)?Convert.ToBoolean(c[key]):fallback;}public static int Number(System.Collections.Generic.Dictionary<string,object> c,string key,int fallback){return c!=null&&c.ContainsKey(key)?Convert.ToInt32(c[key]):fallback;}}
